#!/usr/bin/env python3
"""Make an offline, self-contained gallery from the real SVG files and the preview player."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
manifest=json.loads((ROOT/'manifest.json').read_text())
assets={a['path']:(ROOT/a['path']).read_text() for a in manifest['assets']}
html='''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Timo · настоящий SVG-пакет tlfrobot</title><style>
:root{--ink:#21364b;--blue:#367fc1;--paper:#f4f6f3;--line:#d8e2e5;--muted:#587080;--card:#fff;--amber:#f2b24f;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}main{max-width:1260px;margin:auto;padding:42px 30px 60px}a{color:var(--blue)}h1{font-size:46px;line-height:1.05;letter-spacing:-1.8px;margin:8px 0 16px}h2{font-size:25px;letter-spacing:-.6px;margin:36px 0 14px}h3{margin:0;font-size:17px}.eyebrow{font:700 12px var(--mono);letter-spacing:2px;color:var(--blue)}header{display:grid;grid-template-columns:1fr 230px;gap:35px;align-items:center;margin-bottom:26px}header p{max-width:760px;color:var(--muted);margin:10px 0}.tag{display:inline-block;margin:4px 7px 0 0;border:1px solid var(--line);border-radius:999px;padding:5px 10px;font:12px var(--mono);background:#fff}.hero-art{width:220px;height:220px;background:#e6f1f3;border-radius:50%;display:grid;place-items:center}.hero-art svg{width:190px;height:190px}.notice{padding:15px 19px;background:#fff5df;border-left:4px solid var(--amber);border-radius:4px 12px 12px 4px;margin:20px 0;color:#765322}
.demo{display:grid;grid-template-columns:240px minmax(0,1fr);border:1px solid var(--line);border-radius:22px;overflow:hidden;background:var(--card)}.clip-list{background:#eef3f3;padding:13px;max-height:650px;overflow:auto}.clip-list button{width:100%;display:flex;align-items:center;gap:9px;text-align:left;border:0;background:transparent;box-shadow:none;color:var(--muted);padding:8px;border-radius:8px;font:12px/1.3 var(--mono);cursor:pointer}.clip-list button.active{background:var(--ink);color:#fff}.clip-list small{opacity:.6;font-size:10px}.stage-col{padding:22px;min-width:0}.stage-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.stage-top code{color:var(--blue);font:15px var(--mono)}.stage-title{font-size:19px;font-weight:650}.stage{margin-top:12px;border-radius:16px;background:#fff;border:1px solid #e3eaeb;overflow:hidden}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:14px 0}button,.button{border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);padding:8px 12px;font:inherit;cursor:pointer}button:hover{border-color:var(--blue)}button.primary{background:var(--ink);border-color:var(--ink);color:#fff}.toolbar input[type=range]{flex:1;min-width:110px}.toolbar output{font:12px var(--mono);width:38px}.param-grid{display:flex;flex-wrap:wrap;gap:10px 14px;padding:12px 0;border-top:1px solid var(--line)}.param-grid label{font-size:11px;color:var(--muted);display:flex;flex-direction:column;gap:4px}.param-grid label.check{flex-direction:row;align-items:center;padding-top:17px}.param-grid select,.param-grid input[type=number]{border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);padding:6px;font:12px var(--mono);width:auto;min-width:68px}.param-grid input[type=number]{width:74px}pre{margin:8px 0 0;background:#f3f6f6;border-radius:10px;padding:12px;font:11px/1.5 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere}.hint{font-size:12px;color:var(--muted);margin:10px 0}.frames{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.frame{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden}.frame span{display:block;text-align:center;font:11px var(--mono);padding:5px}.frame svg{display:block;width:100%;height:auto}.inventory-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card{border:1px solid var(--line);background:var(--card);border-radius:14px;overflow:hidden;min-width:0}.art{height:155px;display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#f8faf8 0% 25%,#fff 0% 50%) 50%/18px 18px}.art svg{max-width:130px;max-height:128px}.card-meta{padding:12px}.file-name{font:11px/1.4 var(--mono);overflow-wrap:anywhere;color:var(--muted);margin:5px 0 11px}.card-meta .links{display:flex;gap:12px;align-items:center}.card-meta .links a,.card-meta .links button{font-size:12px}.card-meta .links button{padding:3px 7px}.id{font:11px var(--mono);color:var(--blue);display:inline-block;margin-right:7px}.small-tests{display:flex;gap:28px;align-items:flex-end;flex-wrap:wrap;border:1px solid var(--line);padding:20px;border-radius:14px;background:#fff}.small-tests>div{display:flex;flex-direction:column;align-items:center;gap:6px;font:11px var(--mono);color:var(--muted)}.dark .art,.dark .small-tests{background:#21364b}.dark .small-tests>div{color:#edf3f4}.foot{border-top:1px solid var(--line);margin-top:40px;padding-top:20px;color:var(--muted);font-size:12px}.foot code{font:12px var(--mono)}.readable{max-width:920px}.download-list{display:flex;gap:15px;flex-wrap:wrap}.download-list a{font-size:13px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:950px){.demo{grid-template-columns:1fr}.clip-list{display:flex;overflow:auto;padding:10px;max-height:85px}.clip-list button{width:auto;min-width:128px}.cards{grid-template-columns:repeat(3,minmax(0,1fr))}.frames{overflow:auto}}
@media(max-width:600px){main{padding:22px 14px 40px}header{grid-template-columns:1fr 94px;gap:8px}h1{font-size:34px}.hero-art{width:94px;height:94px}.hero-art svg{width:88px;height:88px}.stage-col{padding:12px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.art{height:124px}.art svg{max-width:110px;max-height:105px}.card-meta{padding:9px}.card h3{font-size:13px}.frames .frame{min-width:110px}.frames{grid-template-columns:repeat(5,110px);padding-bottom:8px}.param-grid{gap:8px}.stage-top code{font-size:12px}}
</style></head><body><main>
<header><div><div class="eyebrow">TLF ROBOT / WORKSHOP ART 1.0</div><h1>Тимо. Теперь вектор.</h1><p>Небольшой смотритель мастерской: переносит кристаллы-компоненты, наносит разметку и изучает пространство. Один персонаж, независимые инструменты, простые движения.</p><div><span class="tag">22 обязательных SVG</span><span class="tag">3 резервных SVG</span><span class="tag">12 отдельных иконок</span></div></div><div class="hero-art" id="hero"></div></header>
<div class="notice">Предыдущие листы были PNG. Здесь — новая упрощённая векторная отрисовка: реальные <code>path / rect / circle / g</code>, без встроенных растров. Это не точная трассировка прежних картинок.</div>
<h2>Движения и состояния</h2><p class="readable">SVG — исходные части. В этой галерее ими управляет отдельный JavaScript-плеер: анимацию можно остановить, перемотать и отменить. Плеер только показывает действия — он не является реализацией Python-библиотеки или проверкой решений.</p>
<div class="demo"><nav class="clip-list" id="clip-list" aria-label="Анимационные шаблоны"></nav><section class="stage-col"><div class="stage-top"><span class="stage-title" id="clip-title"></span><code id="clip-call"></code></div><div class="stage" id="stage"></div>
<div class="toolbar"><button class="primary" id="play">▶ Показать</button><button id="pause">Пауза</button><button id="cancel">Сброс кадра</button><label class="sr-only" for="progress">Прогресс</label><input type="range" id="progress" min="0" max="100" value="0"><output id="progress-value">0%</output><select id="speed" aria-label="Скорость"><option value=".25">¼×</option><option value=".5" selected>½×</option><option value="1">1×</option><option value="2">2×</option></select></div>
<div class="param-grid">
<label data-param="policy">Режим<select id="policy"><option value="relative">relative</option><option value="absolute">absolute</option></select></label>
<label data-param="direction">Направление<select id="direction"><option>north</option><option>east</option><option>south</option><option>west</option></select></label>
<label data-param="heading">Начальный взгляд<select id="heading"><option>north</option><option>east</option><option>south</option><option>west</option></select></label>
<label data-param="turn">Поворот<select id="turn"><option value="left">left −90°</option><option value="right">right +90°</option><option value="around">around +180°</option></select></label>
<label data-param="transfer">Передача<select id="transfer"><option>take</option><option>put</option></select></label>
<label data-param="subject">Датчик<select id="subject"><option value="crystal">crystal</option><option value="paint">paint</option><option value="count">count</option><option value="bag">bag</option></select></label>
<label data-param="result">Результат<select id="result"><option value="true">True / success</option><option value="false">False / failure</option></select></label>
<label data-param="count">В клетке<input id="count" type="number" min="0" max="9999" value="2"></label>
<label data-param="bag">Сумка<select id="bag"><option value="0">0</option><option value="1" selected>1</option><option value="5">5</option><option value="infinite">∞</option></select></label>
<label data-param="input">Тип ввода<select id="input"><option value="key">key</option><option value="click">click</option><option value="time">time</option></select></label>
<label data-param="lifecycle">Состояние<select id="lifecycle"><option>completed</option><option>ready</option><option>cancelled</option></select></label>
<label class="check"><input id="painted" type="checkbox"> Уже закрашено</label>
<label class="check"><input id="reduced" type="checkbox"> Меньше движения</label>
</div><p class="hint" id="clip-hint"></p><pre id="visual-state"></pre></section></div>
<h2>Пять точных кадров</h2><p class="hint">0%, 25%, 50%, 75%, 100% одной анимации. Кадры вычисляются напрямую, без исполнения пропущенных кадров.</p><div class="frames" id="frames"></div>
<div class="inventory-head"><h2>Векторные исходники</h2><button id="background">Тёмный фон</button></div><p class="hint">Каждая ссылка SVG отдаёт настоящий XML-файл. Все ресурсы встроены в эту HTML-галерею; интернет для просмотра не нужен.</p><div class="cards" id="cards"></div>
<h2>Один робот в маленькой клетке</h2><div class="small-tests" id="small-tests"></div>
<h2>Именованные части и соглашения</h2><p class="readable">У <code>robot.svg</code> — <code>viewBox="0 0 128 128"</code>, центр поворота <code>(64,64)</code>, исходное направление на север. <code>body</code>, <code>drive</code>, <code>heading</code>, <code>sensor</code>, <code>gripper-base</code>, <code>gripper-left</code>, <code>gripper-right</code>, <code>roller</code>, <code>eraser</code>, <code>cargo-hatch</code>, <code>eyes</code>, <code>eyelids</code>, <code>shadow</code>. В абсолютном режиме скрывается указатель направления; инструменты и датчик независимы.</p>
<p class="readable">Цифры, <code>True / False / None</code>, клавиши и подписи рисуются живым текстом, а не зашиты в SVG. Ложь датчика — спокойный серо-синий значок, ошибка — предупреждение другой формы, завершение программы — не печать успешной проверки.</p><div class="download-list" id="meta-downloads"></div>
<div class="foot">Timo / Workshop · оригинальная векторная геометрия для tlfrobot. 22 обязательных мастера + 3 графических заготовки + 12 производных UI-иконок. JavaScript-плеер — демонстрационный слой; Pyodide, игровой движок и pygame-адаптер в этот пакет не входят. Все PNG в каталоге desktop получены из этих SVG, а не наоборот.</div>
</main><script id="art-data" type="application/json">__ART__</script><script id="manifest-data" type="application/json">__MANIFEST__</script><script>__PLAYER__</script>
<script>
'use strict';
const assets=JSON.parse(document.getElementById('art-data').textContent);
const manifest=JSON.parse(document.getElementById('manifest-data').textContent);
const $=id=>document.getElementById(id);
TlfRobotArt.mount(assets['robot/robot.svg'],$ ('hero'),0,0,128,128);
const stage=new TlfRobotArt.Stage($('stage'),assets);window.demoStage=stage;
let current='move.step',ctl=null,paused=false;
const frames=[];
for(const p of [0,.25,.5,.75,1]){const wrap=document.createElement('div');wrap.className='frame';const box=document.createElement('div');const label=document.createElement('span');label.textContent=Math.round(p*100)+'%';wrap.append(box,label);$('frames').append(wrap);frames.push([new TlfRobotArt.Stage(box,assets),p]);}
function options(){return {policy:$('policy').value,direction:$('direction').value,heading:$('heading').value,turn:$('turn').value,transfer:$('transfer').value,subject:$('subject').value,result:$('result').value==='true',count:Number($('count').value),bag:$('bag').value==='infinite'?'infinite':Number($('bag').value),input:$('input').value,lifecycle:$('lifecycle').value,painted:$('painted').checked,reduced:$('reduced').checked};}
function stop(){if(ctl){ctl.cancel();ctl=null;}paused=false;$('pause').textContent='Пауза';}
function paintAt(p){const state=stage.render(current,p,options());$('visual-state').textContent=JSON.stringify(state,null,2);$('progress-value').value=Math.round(p*100)+'%';}
function refresh(){stop();const p=Number($('progress').value)/100;paintAt(p);for(const [s,t] of frames)s.render(current,t,options());}
function pick(key){stop();current=key;$('progress').value=0;const c=TlfRobotArt.clips.find(c=>c.key===key);$('clip-title').textContent=c.title;$('clip-call').textContent=c.call;
 document.querySelectorAll('.clip-list button').forEach(b=>b.classList.toggle('active',b.dataset.key===key));
 const visible=new Set(['policy','heading']);
 const byKey={'move.step':['direction'],'turn':['turn'],'crystal.transfer':['transfer','count','bag'],'sense.edge':['direction','result'],'sense.cell':['subject','result','count'],'sense.bag':['bag','subject'],'sense.heading':['direction'],'error.wall':['direction'],'error.object':['subject'],'input.waiting':['input'],'input.received':['input'],'lifecycle':['lifecycle'],'verdict':['result']};
 (byKey[key]||[]).forEach(x=>visible.add(x));document.querySelectorAll('[data-param]').forEach(n=>n.style.display=visible.has(n.dataset.param)?'':'none');
 if(key==='paint.erase')$('painted').checked=true;
 if(key==='sense.bag')$('subject').value='crystal';
 $('clip-hint').textContent=key==='input.waiting'?'Для ожидания клавиши или клика нажмите «Показать», затем клавишу при фокусе на поле либо клетку. Ожидание не завершается само. Для time показывается секундный интервал.':key==='crystal.transfer'?'Здесь показан успешный перенос одного кристалла. Для пустого источника выберите C11. Промежуточные числа — визуальное представление, а не состояние игрового движка.':'Управление ползунком не исполняет Python и не меняет реальный мир. Группа датчика не поворачивает корпус.';
 refresh();}
for(const c of TlfRobotArt.clips){const b=document.createElement('button');b.dataset.key=c.key;const id=document.createElement('small');id.textContent=c.id;const t=document.createElement('span');t.textContent=c.key;b.append(id,t);b.addEventListener('click',()=>pick(c.key));$('clip-list').append(b);}
$('play').addEventListener('click',()=>{stop();$('progress').value=0;const o=options();ctl=stage.play(current,{...o,speed:Number($('speed').value),onProgress:p=>{$('progress').value=p*100;$('progress-value').value=Math.round(p*100)+'%';$('visual-state').textContent=JSON.stringify(stage.last.visual,null,2);}});const owned=ctl;
 ctl.finished.then(value=>{if(ctl===owned){ctl=null;$('progress').value=100;paintAt(1);if(current==='input.waiting'&&o.input!=='time')$('clip-hint').textContent='Получено: '+JSON.stringify(value)+'; продолжение программы может выполняться теперь.';}}).catch(e=>{if(e.name!=='AbortError')console.error(e);});
 if(current==='input.waiting'){$('stage').tabIndex=0;$('stage').focus();}
});
$('pause').addEventListener('click',()=>{if(!ctl)return;paused=!paused;if(paused)ctl.pause();else ctl.resume();$('pause').textContent=paused?'Продолжить':'Пауза';});
$('cancel').addEventListener('click',()=>{stop();$('progress').value=0;paintAt(0);});
$('progress').addEventListener('input',()=>{stop();paintAt(Number($('progress').value)/100);});
for(const n of document.querySelectorAll('.param-grid input,.param-grid select'))n.addEventListener('change',refresh);
$('stage').addEventListener('keydown',e=>{if(ctl&&current==='input.waiting'&&$('input').value==='key'){e.preventDefault();ctl.completeInput(e.key===' '?'space':e.key);}});
$('stage').addEventListener('click',e=>{if(ctl&&current==='input.waiting'&&$('input').value==='click'){
 const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(stage.svg.getScreenCTM().inverse());
 if(pt.x>=24&&pt.x<408&&pt.y>=24&&pt.y<408)ctl.completeInput([Math.floor((pt.x-24)/128),2-Math.floor((pt.y-24)/128)]);
}});
function link(data,type,name,label){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.textContent=label;return a;}
for(const a of manifest.assets){const card=document.createElement('article');card.className='card';const art=document.createElement('div');art.className='art';const vb=a.viewBox;const scale=Math.min(128/vb[2],124/vb[3]);TlfRobotArt.mount(assets[a.path],art,0,0,vb[2]*scale,vb[3]*scale);
 const meta=document.createElement('div');meta.className='card-meta';const h=document.createElement('h3');h.textContent=a.title;const ident=document.createElement('span');ident.className='id';ident.textContent=a.id;h.prepend(ident);const f=document.createElement('p');f.className='file-name';f.textContent=a.path;const links=document.createElement('div');links.className='links';links.append(link(assets[a.path],'image/svg+xml',a.path.split('/').pop(),'SVG-файл'));
 const copy=document.createElement('button');copy.textContent='Код';copy.addEventListener('click',()=>{const tab=window.open();if(tab){const pre=tab.document.createElement('pre');pre.textContent=assets[a.path];pre.style.whiteSpace='pre-wrap';tab.document.body.append(pre);}});links.append(copy);meta.append(h,f,links);card.append(art,meta);$('cards').append(card);}
for(const size of [32,48,64,96,128]){const box=document.createElement('div');TlfRobotArt.mount(assets['robot/robot.svg'],box,0,0,size,size);const label=document.createElement('span');label.textContent=size+' px';box.append(label);$('small-tests').append(box);}
$('background').addEventListener('click',()=>{document.body.classList.toggle('dark');$('background').textContent=document.body.classList.contains('dark')?'Светлый фон':'Тёмный фон';});
$('meta-downloads').append(link(JSON.stringify(manifest,null,2),'application/json','manifest.json','Manifest / точки крепления'),link(assets['robot/robot.svg'],'image/svg+xml','robot.svg','Мастер робота'));
pick(current);
</script></body></html>'''
def safe(obj):return json.dumps(obj,ensure_ascii=False).replace('</','<\\/')
html=html.replace('__ART__',safe(assets)).replace('__MANIFEST__',safe(manifest)).replace('__PLAYER__',(ROOT/'animation/player.js').read_text())
(ROOT/'gallery.html').write_text(html,encoding='utf-8')
print('Gallery bytes:',len(html.encode()))
